<?php
declare(strict_types=1);
namespace Hostider\OfflineBackup;
use Hostider\Core\Security\Crypto;
final class ManagedFiles
{
 public static function catalog(array $tables):array{$out=[];foreach($tables['support_mail_files'] as $r){Guard::require(!($r['purged_at']!==null&&$r['physical_removed']==='0'),'RETENTION_PENDING');if($r['physical_removed']==='1'){continue;}$out['attachments/'.$r['id'].'.bin']=['group'=>'attachments','name'=>$r['id'].'.bin','id'=>$r['id'],'logical_sha256'=>$r['sha256'],'logical_size'=>(int)$r['byte_count'],'row_sha256'=>Guard::hash($r)];}$docs=[];foreach($tables['billing_official_documents'] as $r){$docs[$r['upload_id']]=$r;}foreach($tables['billing_uploads'] as $r){if((int)$r['received_bytes']===0){continue;}Guard::require($r['finalized']==='1'&&isset($docs[$r['id']]),'UPLOAD_PENDING');$d=$docs[$r['id']];Guard::require((int)$d['size_bytes']===(int)$r['received_bytes'],'DOCUMENT_LINK');$out['documents/'.$r['id'].'.pdf']=['group'=>'documents','name'=>$r['id'].'.pdf','id'=>$r['id'],'logical_sha256'=>$d['sha256'],'logical_size'=>(int)$d['size_bytes'],'row_sha256'=>Guard::hash([$r,$d])];}ksort($out);Guard::require(count($out)<=Guard::MAX_FILES,'FILE_COUNT');return $out;}
 public static function names(array $meta):void{Guard::fields($meta,['group','name','id','logical_sha256','logical_size','row_sha256']);Guard::require(in_array($meta['group'],['attachments','documents'],true)&&is_string($meta['id'])&&preg_match('/\A[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}\z/D',$meta['id'])===1&&$meta['name']===$meta['id'].($meta['group']==='attachments'?'.bin':'.pdf'),'FILE_NAME');foreach(['logical_sha256','row_sha256'] as $n){Guard::require(is_string($meta[$n])&&preg_match('/\A[a-f0-9]{64}\z/D',$meta[$n])===1,'FILE_DIGEST');}Guard::require(is_int($meta['logical_size'])&&$meta['logical_size']>=8&&$meta['logical_size']<=($meta['group']==='attachments'?16384:10485760),'FILE_SIZE');}
 public static function bytes(Workspace $w,array $meta,bool $target=false,bool $frozen=true):string{self::names($meta);$path=$w->fileRoot($meta['group'],$target).'/'.$meta['name'];$s=Guard::file($path,$frozen?0400:0600);Guard::require($s['size']<=($meta['group']==='attachments'?24000:10485760),'PHYSICAL_BOUND');$f=Guard::open($path,'rb',$frozen?0400:0600);try{Guard::require(flock($f,LOCK_SH|LOCK_NB),'FILE_BUSY');$b=stream_get_contents($f,10485761);Guard::require(is_string($b)&&strlen($b)===$s['size'],'FILE_READ');$after=fstat($f);Guard::require($after['size']===$s['size']&&$after['mtime']===$s['mtime']&&$after['ctime']===$s['ctime'],'FILE_CHANGED');}finally{fclose($f);}$plain=$meta['group']==='attachments'?(new Crypto($w->applicationKey()))->decrypt($b,'support-file:'.$meta['id']):$b;Guard::require(strlen($plain)===$meta['logical_size']&&hash_equals($meta['logical_sha256'],hash('sha256',$plain)),'FILE_LOGICAL_INTEGRITY');if($meta['group']==='documents'){(new \Hostider\Billing\DocumentStore($w->fileRoot('documents',$target),dirname(__DIR__,2).'/public'))->validate($plain);}return $b;}
 public static function auxiliary(string $p,bool $frozen):void{clearstatcache(true,$p);$mode=fileperms($p)&0777;Guard::require($frozen?$mode===0400:in_array($mode,[0600,0644],true),'LOCK_MODE');$s=Guard::file($p,$mode);Guard::require($s['size']===0,'LOCK_FILE');}
 public static function inspect(Workspace $w,array $catalog,bool $target=false,bool $frozen=true):array{$seen=[];$total=0;foreach(['attachments','documents'] as $g){Guard::directory($w->fileRoot($g,$target),$frozen?0500:0700);foreach(new \DirectoryIterator($w->fileRoot($g,$target)) as $f){if($f->isDot()){continue;}if($f->getFilename()==='.lock'&&$g==='attachments'){self::auxiliary($f->getPathname(),$frozen);continue;}$k=$g.'/'.$f->getFilename();Guard::require(isset($catalog[$k]),'UNREGISTERED_FILE');$seen[]=$k;}}sort($seen);Guard::require($seen===array_keys($catalog),'MISSING_FILE');$out=[];foreach($catalog as $k=>$m){$b=self::bytes($w,$m,$target,$frozen);$total+=strlen($b);Guard::require($total<=Guard::MAX_FILE_BYTES,'FILE_TOTAL');$out[$k]=['sha256'=>hash('sha256',$b),'bytes'=>strlen($b)];}return $out;}
 public static function decoded(array $image):array{$t=[];foreach(['support_mail_files','billing_official_documents','billing_uploads'] as $n){Guard::require(isset($image['tables'][$n],$image['metadata'][$n]),'FILE_TABLES');$t[$n]=NativeSchema::plain($image['tables'][$n],$image['metadata'][$n]['columns']);}return $t;}
}
